using System;
using System.IO;
using System.Linq;
using UnityEngine;
using UnityEditor;
using UnityEditor.SceneManagement;
public static class MatchFisherShopStyle
{
 static void Capture(Transform h){var go=new GameObject("Temporary_Fisher_Style_Camera");var rt=new RenderTexture(1400,1000,24);var texture=new Texture2D(1400,1000,TextureFormat.RGB24,false);var old=RenderTexture.active;var canvases=UnityEngine.Object.FindObjectsByType<Canvas>(FindObjectsSortMode.None).Where(c=>c.enabled).ToArray();try{foreach(var c in canvases)c.enabled=false;var cam=go.AddComponent<Camera>();cam.transform.position=h.TransformPoint(new Vector3(-10,6,-13));cam.transform.LookAt(h.TransformPoint(new Vector3(0,1.7f,0)));cam.fieldOfView=49;cam.farClipPlane=120;cam.clearFlags=CameraClearFlags.SolidColor;cam.backgroundColor=new Color(.19f,.25f,.29f);cam.targetTexture=rt;cam.Render();RenderTexture.active=rt;texture.ReadPixels(new Rect(0,0,1400,1000),0,0);texture.Apply();File.WriteAllBytes("Docs/assets/examples/Fisher_ShopStyle_Exterior.png",texture.EncodeToPNG());}finally{foreach(var c in canvases)c.enabled=true;RenderTexture.active=old;UnityEngine.Object.DestroyImmediate(go);UnityEngine.Object.DestroyImmediate(rt);UnityEngine.Object.DestroyImmediate(texture);}}
 public static string Main(){var scene=UnityEngine.SceneManagement.SceneManager.GetActiveScene();if(scene.path!="Assets/Scenes/CastleServicesWorkshop.unity"||scene.isDirty||EditorApplication.isPlayingOrWillChangePlaymode)throw new Exception("Saved castle Edit Mode required");if(!File.Exists("Library/WorkshopBackups/DB-ON-079-ShopStyle/OwnerSaved.unity"))throw new Exception("Owner checkpoint required");var houses=GameObject.Find("Castle_Services_Prototype").transform.Find("03_Service_Houses");var reference=houses.Find("01_Supplies");var fisher=houses.Find("02_Armory");int count=0;
  foreach(string group in new[]{"01_Floor","02_Walls","03_Frame","04_Roof","05_Porch"}){var src=reference.Find(group).GetComponentsInChildren<MeshRenderer>();foreach(var dst in fisher.Find(group).GetComponentsInChildren<MeshRenderer>()){var mesh=dst.GetComponent<MeshFilter>().sharedMesh;var match=src.FirstOrDefault(r=>r.GetComponent<MeshFilter>().sharedMesh==mesh);if(match==null)throw new Exception("No shop style match for "+group+"/"+dst.name+" mesh="+mesh.name);Undo.RecordObject(dst,"Стиль Пятёрочки для дома рыбака");dst.sharedMaterials=match.sharedMaterials;PrefabUtility.RecordPrefabInstancePropertyModifications(dst);if(!dst.sharedMaterials.SequenceEqual(match.sharedMaterials))throw new Exception("Material mismatch");count++;}}
  var subfloor=fisher.Find("18_Wooden_Subfloor");if(subfloor!=null){var rr=subfloor.GetComponent<Renderer>();Undo.RecordObject(rr,"Деревянная подложка");rr.sharedMaterial=reference.Find("02_Walls").GetComponentInChildren<Renderer>().sharedMaterials.Last();}
  if(fisher.Find("16_Run_Interior").gameObject.activeSelf||!fisher.Find("17_Boarded_Entrance").gameObject.activeSelf)throw new Exception("Unexpected furniture/barrier state");Capture(fisher);AssetDatabase.SaveAssets();EditorSceneManager.MarkSceneDirty(scene);if(!EditorSceneManager.SaveScene(scene))throw new Exception("Save failed");Selection.activeGameObject=fisher.gameObject;SceneView.lastActiveSceneView?.LookAt(fisher.TransformPoint(new Vector3(0,1.8f,0)),fisher.rotation*Quaternion.Euler(22,-30,0),8,false,true);string report="PASS: "+count+" renderers use exact shop materials, including wood/woodDark window frames, ClearWindowGlass and RustTiles palette. Meshes, colliders, transforms, blocked entrance and empty interior preserved. Owner scene saved before work; final scene saved.";File.WriteAllText("Docs/assets/examples/FISHER_SHOP_STYLE_VALIDATION.txt",report);return report;
 }
}
